import assert from 'node:assert/strict';import {randomUUID} from 'node:crypto';
import {lanes as fifteen} from './maintenance-fifteen-lanes.mjs';
import {identity} from './model-settings.mjs';
export const lanes={...fifteen,productSettings:{key:'product_settings',begin:()=>({action:'begin',...identity}),changes:{reader_enabled:{action:'set',value:false}}}};
const isRead=name=>['inspectSourceCache','inspectConversations'].includes(name);
export async function verifyTwoHundredFortyDirections(request){let pairs=0,old210=0;for(const [old,a]of Object.entries(lanes))for(const [newer,b]of Object.entries(lanes)){if(old===newer)continue;const ready=(await request(old,a.begin()))[a.key];assert.ok(isRead(old)?ready.status==='reported':ready.reference,old);const next=(await request(newer,b.begin()))[b.key];assert.ok(isRead(newer)?next.status==='reported':next.reference,newer);if(!isRead(old)){const q=a.change?{action:'save',...identity,reference:ready.reference,change:a.change}:a.changes?{action:'save',...identity,reference:ready.reference,changes:a.changes}:old==='memoryForget'?{action:'confirm',reference:ready.reference}:old==='conversationManagement'?{action:'prepare',...identity,reference:ready.reference,invocation:randomUUID()}:old==='handwritingRecords'?{action:'confirm-remove',...identity,reference:ready.reference,invocation:randomUUID()}:old==='selectedArchive'?{action:'confirm-export',...identity,reference:ready.reference,invocation:randomUUID()}:old==='ordinaryRestore'?{action:'confirm',...identity,reference:ready.reference,invocation:randomUUID()}:old==='sourceCacheCleanup'?{action:'confirm',...identity,reference:ready.reference,invocation:randomUUID()}:{action:'confirm',...identity,reference:ready.reference};const v=(await request(old,q))[a.key];assert.ok(['invalidated','unavailable','not-dispatched'].includes(v.state),`${old} after ${newer}: ${v.state}`);}if(old!=='productSettings'&&newer!=='productSettings')old210++;pairs++;}assert.equal(pairs,240);assert.equal(old210,210);}
export async function verifyTwoHundredFortyBusyDirections(request,control){let pairs=0;for(const [old,a]of Object.entries(lanes)){await control.hold();const q=a.begin();if(old==='selectedArchive'||old==='handwritingRecords')q.action='inspect';const pending=request(old,q);await control.entered();try{const before=await control.snapshot();for(const [newer,b]of Object.entries(lanes)){if(old===newer)continue;const v=(await request(newer,b.begin()))[b.key];assert.equal(isRead(newer)?v.status:v.state,'busy',`${old} holds, ${newer} refused`);assert.deepEqual(await control.snapshot(),before,'Busy has no hook/cancel/raw side effect');pairs++;}}finally{await control.release();}await pending;}assert.equal(pairs,240);}
